__global__ void blur_kernel(const unsigned char* in,unsigned char* out,BlurConfig c){int i=blockIdx.x*blockDim.x+threadIdx.x,n=c.width*c.height*c.channels;if(i>=n)return;int ch=i%c.channels,x=(i/c.channels)%c.width,y=i/(c.width*c.channels),r=c.kernel_size/2;if(c.mode==BlurMode::Median){unsigned char values[225];int count=0;for(int dy=-r;dy<=r;++dy)for(int dx=-r;dx<=r;++dx){int px=max(0,min(c.width-1,x+dx)),py=max(0,min(c.height-1,y+dy));values[count++]=in[(py*c.width+px)*c.channels+ch];}for(int a=0;a<count;++a){int best=a;for(int b=a+1;b<count;++b)if(values[b]<values[best])best=b;unsigned char t=values[a];values[a]=values[best];values[best]=t;}out[i]=values[count/2];return;}float sum=0,wtotal=0,inv=1.f/(2.f*c.sigma*c.sigma);for(int dy=-r;dy<=r;++dy)for(int dx=-r;dx<=r;++dx){int px=reflect101(x+dx,c.width),py=reflect101(y+dy,c.height);float w=c.mode==BlurMode::Average?1.f:expf(-(dx*dx+dy*dy)*inv);sum+=w*in[(py*c.width+px)*c.channels+ch];wtotal+=w;}out[i]=(unsigned char)fminf(255.f,fmaxf(0.f,rintf(sum/wtotal)));}
__global__ void bilateral_blur_kernel(const unsigned char* in,unsigned char* out,BilateralBlurConfig c){int i=blockIdx.x*blockDim.x+threadIdx.x,n=c.width*c.height*c.channels;if(i>=n)return;const int ch=i%c.channels,x=(i/c.channels)%c.width,y=i/(c.width*c.channels),radius=c.radius;const float spatial_inv=1.f/(2.f*c.sigma_space*c.sigma_space),color_inv=1.f/(2.f*c.sigma_color*c.sigma_color);float sum=0.f,weight_sum=0.f;for(int dy=-radius;dy<=radius;++dy)for(int dx=-radius;dx<=radius;++dx){const int px=reflect101(x+dx,c.width),py=reflect101(y+dy,c.height),sample=(py*c.width+px)*c.channels;float color_distance=0.f;for(int other=0;other<c.channels;++other){const float difference=(float)in[sample+other]-(float)in[(y*c.width+x)*c.channels+other];color_distance+=difference*difference;}const float weight=expf(-((float)(dx*dx+dy*dy)*spatial_inv+color_distance*color_inv));weight_sum+=weight;sum+=weight*in[sample+ch];}const float value=fminf(255.f,fmaxf(0.f,sum/weight_sum));out[i]=static_cast<unsigned char>(floorf(value+.5f));}
