  const int ch=i%c.channels,x=(i/c.channels)%c.width,y=i/(c.width*c.channels),radius=c.spatial_radius;
  const int center=(y*c.width+x)*c.channels; const float color_limit=c.color_radius*c.color_radius;
  float sum=0.f;int count=0;
  for(int dy=-radius;dy<=radius;++dy)for(int dx=-radius;dx<=radius;++dx){
    const int px=reflect101(x+dx,c.width),py=reflect101(y+dy,c.height),sample=(py*c.width+px)*c.channels;float distance=0.f;
    for(int other=0;other<c.channels;++other){const float difference=static_cast<float>(source[sample+other])-static_cast<float>(current[center+other]);distance+=difference*difference;}
    if(distance<=color_limit){++count;sum+=static_cast<float>(source[sample+ch]);}
  }
  const float value=count?sum/static_cast<float>(count):static_cast<float>(current[center+ch]);
