}
__global__ void mean_shift_blur_finalize(const float* state,unsigned char* out,int n){const int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)out[i]=static_cast<unsigned char>(floorf(fminf(255.f,fmaxf(0.f,state[i]))+.5f));}
__global__ void advanced_blur_kernel(const unsigned char* in,unsigned char* out,AdvancedBlurConfig c){int i=blockIdx.x*blockDim.x+threadIdx.x,n=c.width*c.height*c.channels;if(i>=n)return;int ch=i%c.channels,x=(i/c.channels)%c.width,y=i/(c.width*c.channels),r=c.kernel_size/2;float angle=c.angle_degrees*3.14159265358979323846f/180.f,co=cosf(angle),si=sinf(angle),norm=0.f;float kernel[225];for(int dy=-r;dy<=r;++dy)for(int dx=-r;dx<=r;++dx){float xp=co*dx+si*dy,yp=-si*dx+co*dy,qx=xp/c.sigma_x,qy=yp/c.sigma_y,w=expf(-.5f*(qx*qx+qy*qy));kernel[(dy+r)*c.kernel_size+dx+r]=w;norm+=w;}float sum=0.f;for(int dy=-r;dy<=r;++dy)for(int dx=-r;dx<=r;++dx){int px=reflect101(x+dx,c.width),py=reflect101(y+dy,c.height);sum+=(kernel[(dy+r)*c.kernel_size+dx+r]/norm)*in[(py*c.width+px)*c.channels+ch];}out[i]=(unsigned char)fminf(255.f,fmaxf(0.f,rintf(sum)));}
