__global__ void glass_blur_gaussian_kernel(const unsigned char* in,unsigned char* out,GlassBlurConfig c,int radius){int i=blockIdx.x*blockDim.x+threadIdx.x,n=c.width*c.height*c.channels;if(i>=n)return;int ch=i%c.channels,x=(i/c.channels)%c.width,y=i/(c.width*c.channels);float inv=1.f/(2.f*c.sigma*c.sigma),sum=0.f,norm=0.f;for(int dy=-radius;dy<=radius;++dy)for(int dx=-radius;dx<=radius;++dx){float weight=expf(-(dx*dx+dy*dy)*inv);sum+=weight*in[(reflect101(y+dy,c.height)*c.width+reflect101(x+dx,c.width))*c.channels+ch];norm+=weight;}out[i]=(unsigned char)fminf(255.f,fmaxf(0.f,rintf(sum/norm)));}
__global__ void glass_blur_swap_kernel(unsigned char* image,GlassBlurConfig c,const GlassBlurSwap* swaps){if(blockIdx.x!=0||threadIdx.x!=0)return;const int width=c.width-2*c.max_delta,height=c.height-2*c.max_delta;const unsigned long long count=(unsigned long long)c.iterations*width*height;for(unsigned long long k=0;k<count;++k){const int position=(int)(k%(unsigned long long)(width*height)),x=c.max_delta+position%width,y=c.max_delta+position/width;GlassBlurSwap swap;if(swaps)swap=swaps[k];else{const unsigned long long span=(unsigned long long)(2*c.max_delta+1);swap.dx=(signed char)((int)(glass_blur_splitmix64(c.seed+2*k)%span)-c.max_delta);swap.dy=(signed char)((int)(glass_blur_splitmix64(c.seed+2*k+1)%span)-c.max_delta);}const int sx=x+swap.dx,sy=y+swap.dy;for(int ch=0;ch<c.channels;++ch){unsigned char* a=image+((y*c.width+x)*c.channels+ch);unsigned char* b=image+((sy*c.width+sx)*c.channels+ch);unsigned char value=*a;*a=*b;*b=value;}}}
int glass_blur_radius_cuda(float sigma){int radius=(int)ceilf(3.f*sigma);if(radius<1||radius>15)throw std::invalid_argument("glass blur sigma produces an unsupported kernel");return radius;}
void validate_glass_blur_cuda(const std::uint8_t* in,const std::uint8_t* out,const GlassBlurConfig& c){if(!in||!out||c.width<=0||c.height<=0||c.channels<=0||!isfinite(c.sigma)||c.sigma<=0.f||c.max_delta<0||c.max_delta>127||c.iterations<0||c.max_delta>c.width/2||c.max_delta>c.height/2)throw std::invalid_argument("invalid glass blur configuration");glass_blur_radius_cuda(c.sigma);}
